<header class="flex justify-between items-center w-full px-panel-padding h-track-height-md bg-surface-container dark:bg-surface-container border-b border-outline-variant flex-shrink-0 z-50">
  <div class="flex items-center gap-6">
    <img alt="Qamuz Studio Logo" class="h-8 w-8 rounded" src="/branding/qamuz/icon-dark.png">
    <h1 class="font-headline-md text-headline-md font-bold text-primary dark:text-primary">Qamuz Studio 1.0</h1>
    <nav class="hidden md:flex items-center gap-4 ml-8">
      <a class="font-headline-md text-headline-md text-on-surface-variant hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded flex items-center gap-1" href="/">
        <span class="material-symbols-outlined text-[18px]">home</span>Home
      </a>
      <a class="font-headline-md text-headline-md text-on-surface-variant hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded" href="#">File</a>
      <a class="font-headline-md text-headline-md text-on-surface-variant hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded" href="#">Edit</a>
      <a class="font-headline-md text-headline-md text-on-surface-variant hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded" href="#">Track</a>
      <a class="font-headline-md text-headline-md text-on-surface-variant hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded" href="#">Mix</a>
      <a class="font-headline-md text-headline-md text-primary font-bold hover:bg-surface-variant transition-colors cursor-pointer active:scale-95 px-2 py-1 rounded" href="#">View</a>
