      <button class="p-1 rounded text-on-surface-variant hover:text-on-surface hover:bg-surface-variant"><span class="material-symbols-outlined text-[18px]">content_cut</span></button>
      <button class="p-1 rounded text-on-surface-variant hover:text-on-surface hover:bg-surface-variant"><span class="material-symbols-outlined text-[18px]">format_paint</span></button>
